import sys, json, time, os
sys.path.insert(0,'/tmp/ref')
from lsp import Client, initialize
ENV={"HOME":"/tmp/home-lspfeat","PATH":"/tmp/lspws/bin:"+os.environ["PATH"],"RUST_LOG":"debug"}
WS="/tmp/lspws/ws"
mode=sys.argv[1]
c = Client(args=["--stdio"], cwd="/tmp/lspws/scratch", env=ENV)
initialize(c, root=None); time.sleep(2); c.err.clear()
T0=time.time()
def openf(uri, ver=1):
    c.send({"jsonrpc":"2.0","method":"textDocument/didOpen","params":{"textDocument":{"uri":uri,"languageId":"rust","version":ver,"text":"pub fn z(){}"}}})
    print("  >>> t=%.4f didOpen %s"%(time.time()-T0, uri.split('/')[-1]), flush=True)
if mode=="same":
    for k in range(8): openf("file://"+WS+"/crate1/src/lib.rs", k+1)
elif mode=="diff":
    for k in range(1,7): openf("file://"+WS+"/crate1/src/m%d.rs"%k, k)
elif mode=="spaced50":
    for k in range(1,7):
        openf("file://"+WS+"/crate1/src/m%d.rs"%k, k); time.sleep(0.05)
elif mode=="spaced150":
    for k in range(1,7):
        openf("file://"+WS+"/crate1/src/m%d.rs"%k, k); time.sleep(0.15)
time.sleep(6)
for l in c.errs(): print(l, flush=True)
c.close()
PY
